import logging
from datetime import datetime, timezone
from typing import Dict, Any

from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.responses import JSONResponse

from app.config import Settings
from app.services.health_service import HealthService, HealthStatus
from app.utils.logging_config import setup_logging

# Initialize settings and logging
settings = Settings()
setup_logging(settings.LOG_LEVEL)
logger = logging.getLogger(__name__)

app = FastAPI(
    title=settings.SERVICE_NAME,
    version=settings.SERVICE_VERSION,
    description="Swarm OS Advanced Health Monitoring Microservice",
)

# Dependency for HealthService
def get_health_service() -> HealthService:
    """Provides a HealthService instance."""
    return HealthService(simulate_failure=settings.SIMULATE_FAILURE)

@app.get("/health", response_model=HealthStatus, summary="Service Health Check")
async def get_service_health(
    health_service: HealthService = Depends(get_health_service)
) -> JSONResponse:
    """
    Performs a comprehensive health check of the service and its dependencies.
    Returns a detailed status report.
    """
    request_id = "req-" + datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S%f") # Simple request ID for logging

    logger.info(f"[{request_id}] Received health check request.", extra={"request_id": request_id})

    try:
        status_report = await health_service.check_health()
        response_data: Dict[str, Any] = {
            "status": "healthy" if status_report.is_healthy else "unhealthy",
            "service_name": settings.SERVICE_NAME,
            "version": settings.SERVICE_VERSION,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "details": status_report.details,
        }

        if not status_report.is_healthy:
            logger.warning(
                f"[{request_id}] Health check failed: {status_report.error_message}",
                extra={"request_id": request_id, "error": status_report.error_message}
            )
            return JSONResponse(
                content=response_data,
                status_code=status.HTTP_503_SERVICE_UNAVAILABLE
            )
        
        logger.info(f"[{request_id}] Health check successful.", extra={"request_id": request_id})
        return JSONResponse(content=response_data, status_code=status.HTTP_200_OK)

    except Exception as e:
        logger.exception(
            f"[{request_id}] An unexpected error occurred during health check.",
            extra={"request_id": request_id, "error_type": type(e).__name__, "error_message": str(e)}
        )
        error_details = {
            "internal_check": "FAILED",
            "error": f"Unexpected internal error: {str(e)}"
        }
        response_data = {
            "status": "unhealthy",
            "service_name": settings.SERVICE_NAME,
            "version": settings.SERVICE_VERSION,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "details": error_details,
        }
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=response_data
        )

@app.on_event("startup")
async def startup_event():
    """Actions to perform on application startup."""
    logger.info(f"{settings.SERVICE_NAME} v{settings.SERVICE_VERSION} starting up.")

@app.on_event("shutdown")
async def shutdown_event():
    """Actions to perform on application shutdown."""
    logger.info(f"{settings.SERVICE_NAME} v{settings.SERVICE_VERSION} shutting down.")